4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Shared SHA-256 hashing used to derive stable identifiers from an owner's own fields
10	 * (the customer code and the household id). Both take a fixed-length upper-case hex prefix
11	 * of the digest, so the derivation lives here once rather than being copied per caller.
12	 */
13	final class Hashes {
14	
15	    private Hashes() {
16	    }
17	
18	    /**
19	     * The first {@code length} characters of the SHA-256 digest of {@code value}, rendered
20	     * as upper-case hex over the UTF-8 bytes of the input.
21	     */
22	    static String upperHexPrefix(String value, int length) {
23	        return hex(value).substring(0, length).toUpperCase(Locale.ROOT);
24	    }
25	
26	    private static String hex(String value) {
27	        try {
28	            byte[] digest = MessageDigest.getInstance("SHA-256")
29	                    .digest(value.getBytes(StandardCharsets.UTF_8));
30	            StringBuilder hex = new StringBuilder(digest.length * 2);
31	            for (byte b : digest) {
32	                hex.append(String.format("%02x", b));
33	            }
34	            return hex.toString();
35	        }
36	        catch (NoSuchAlgorithmException e) {
37	            throw new IllegalStateException("SHA-256 not available", e);
38	        }
39	    }
40	}
